ST.xhtml:p:
R_Trigger1(CLK := g_biLengthCheckOpen);
R_Trigger2(CLK := g_biLengthCheckClose);
R_Trigger3(CLK := g_biLoadCylinder4Close);

IF R_Trigger1.Q THEN
  nCalState := 1;
  g_boLengthCheckDone1 := FALSE;
  g_boLengthCheckDone2 := FALSE;
END_IF;
IF R_Trigger2.Q THEN
  g_boLengthCheckDone1 := FALSE;
  g_boLengthCheckDone2 := FALSE;
END_IF;

IF R_Trigger3.Q THEN
  g_boLoadCylinder4 := FALSE;
END_IF;

IF Axis_Load.NCTOPLC.ACTPOS >= dCylinderPos1 - dAvoidDistance1 THEN
  g_boLoadCylinder1 := FALSE;
END_IF;
IF Axis_Load.NCTOPLC.ACTPOS >= dCylinderPos2 - dAvoidDistance2 THEN
  g_boLoadCylinder2 := FALSE;
END_IF;
IF Axis_Load.NCTOPLC.ACTPOS >= dCylinderPos3 - dAvoidDistance3 THEN
  g_boLoadCylinder3 := FALSE;
END_IF;

CASE nCalState OF
  0:
    nCalState := 0;
  1:
    IF Axis_Load.NCTOPLC.ACTPOS < dCylinderPos1 - dAvoidDistance1 THEN
      g_boLoadCylinder1 := TRUE;
    END_IF;
    IF Axis_Load.NCTOPLC.ACTPOS < dCylinderPos2 - dAvoidDistance2 THEN
      g_boLoadCylinder2 := TRUE;
    END_IF;
    IF (Axis_Load.NCTOPLC.ACTPOS < dCylinderPos1 - dAvoidDistance1) OR (Axis_Load.NCTOPLC.ACTPOS < dCylinderPos2 - dAvoidDistance2) THEN
      CylinderDelay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinderDelay)));
      IF CylinderDelay.Q THEN
        CylinderDelay(IN := FALSE);
        nCalState := 2;
      END_IF;
    ELSE
      nCalState := 2;
    END_IF;
  2:
    IF g_bLengthCheck4 THEN
      nCalState := 3;    
    ELSE
      g_boLoadCylinder1 := FALSE;
      g_boLoadCylinder2 := FALSE;
      nCalState := 21;
      g_bNoPipeWarn :=TRUE;
    END_IF;
  3:
    g_LoadAbs.Execute := TRUE;
    g_LoadAbs.Position := g_dLoadMaxLimit;
    g_LoadAbs.Velocity := dMoveVel;
    IF g_bLengthCheck1 OR g_bLengthCheck2 THEN
      nCalState := 4;
    END_IF;  
    IF g_bLengthCheck3 THEN
      nCalState := 7;
      dTriggerPos := Axis_Load.NCTOPLC.ACTPOS;
      IF Axis_Load.NCTOPLC.ACTPOS < dCylinderPos3 - dAvoidDistance3 THEN
        g_boLoadCylinder3 := TRUE;
      END_IF;
    END_IF;
    IF g_LoadAbs.CommandAborted OR g_LoadAbs.Error THEN
      g_LoadAbs.Execute := FALSE;
      nCalState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nCalState := 20;
      nCalStateLast := 3;
    END_IF;
  4:
    g_LoadAbs.Execute := FALSE;
    g_LoadStop.Execute := TRUE;
    IF g_LoadStop.Done THEN
      g_LoadStop.Execute := FALSE;
      nCalState := 5;
    END_IF;
    IF g_LoadStop.Error OR g_LoadStop.CommandAborted THEN
      g_LoadStop.Execute := FALSE;
      nCalState := 0;
    END_IF;
  5:
    IF Axis_Load.NCTOPLC.ACTPOS < dCylinderPos3 - dAvoidDistance3 THEN
      g_boLoadCylinder3 := TRUE;
      CylinderDelay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinderDelay)));
      IF CylinderDelay.Q THEN
        CylinderDelay(IN := FALSE);
        nCalState := 6;
      END_IF;
    ELSE
      nCalState := 6;
    END_IF;
  6:
    g_LoadAbs.Execute := TRUE;
    g_LoadAbs.Position := g_dLoadMaxLimit;
    g_LoadAbs.Velocity := dMoveVel;
    IF g_bLengthCheck3 THEN
      nCalState := 7;
      dTriggerPos := Axis_Load.NCTOPLC.ACTPOS;
    END_IF;
    IF g_LoadAbs.CommandAborted OR g_LoadAbs.Error THEN
      g_LoadAbs.Execute := FALSE;
      nCalState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nCalState := 20;
      nCalStateLast := 6;
    END_IF;
  7:
    g_LoadAbs.Execute := FALSE;
    g_LoadStop.Execute := TRUE;
    IF g_LoadStop.Done THEN
      g_LoadStop.Execute := FALSE;
      g_fOvershootDistance := Axis_Load.NCTOPLC.ACTPOS - dTriggerPos;
      nCalState := 8;
    END_IF;
    IF g_LoadStop.Error OR g_LoadStop.CommandAborted THEN
      g_LoadStop.Execute := FALSE;
      nCalState := 0;
    END_IF;
  8: 
    dLmZDistance := dLsZDistance - (g_dLoadMaxLimit - g_dTotalLength);
    nPartNum := TRUNC(((g_dTotalLength - dTriggerPos - dZCDistance - g_fPipeHead - dFixedTailLength)/(g_fPartLenght + g_dSlitLength)));
    g_dPipeLength := g_dTotalLength - dTriggerPos;
    g_foPartNum := DINT_TO_LREAL(TRUNC((g_dPipeLength - g_fPipeHead - dLmZDistance)/(g_fPartLenght + g_dSlitLength)));
    g_boLengthCheckDone1 := TRUE;
    IF bFirstFlag THEN
      g_dPipeTailLength := dLastPartNum;
      dLastPartNum := g_dPipeLength - DINT_TO_LREAL(nPartNum)*(g_fPartLenght + g_dSlitLength) - g_fPipeHead;

      g_dLastPipeTail := dLastPipeTail;
      dLastPipeTail := g_dPipeLength - g_fPipeHead - dLmZDistance - g_foPartNum*(g_fPartLenght + g_dSlitLength);
    ELSE
      g_dPipeTailLength := g_dPipeLength - DINT_TO_LREAL(nPartNum)*(g_fPartLenght + g_dSlitLength) - g_fPipeHead;
      dLastPartNum := g_dPipeTailLength;

      g_dLastPipeTail := g_dPipeLength - g_fPipeHead - dLmZDistance - g_foPartNum*(g_fPartLenght + g_dSlitLength);
      dLastPipeTail := g_dLastPipeTail;
      bFirstFlag := TRUE;
    END_IF;
    g_foCalPaRTest := g_dLastPipeTail;
    nCalState := 9;
  9:
    IF g_biGetPartNum THEN
      g_foPartNum := DINT_TO_LREAL(nPartNum) - g_foPartNum;
      nCalState := 10;
    END_IF;
  10:
    g_boLoadCylinder4 := TRUE;
    CylinderDelay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinderDelay)));
    IF CylinderDelay.Q THEN
      CylinderDelay(IN := FALSE);
      g_boLengthCheckDone2 := TRUE;   
      nCalState := 0; 
    END_IF;
  20:
    g_LoadAbs.Execute := FALSE;
    g_LoadStop.Execute := TRUE;
    IF g_LoadStop.Done AND g_bPlcStartBuffer THEN
      g_LoadStop.Execute := FALSE;
      nCalState := nCalStateLast;
    END_IF;
    IF g_LoadStop.CommandAborted OR g_LoadStop.Error THEN
      g_LoadStop.Execute := FALSE;
      nCalState := 0;
    END_IF;
  21:
    IF g_bPlcStartBuffer THEN
      nCalState := 1;
    END_IF;
END_CASE;
g_noCalPartTest := nPartNum;
IF g_bPlcResetBuffer THEN
  nCalState := 0;
  nCalStateLast := 0;
  g_LoadAbs.Execute := FALSE;
  g_LoadStop.Execute := FALSE;
  g_boLoadCylinder1 := FALSE;
  g_boLoadCylinder2 := FALSE;
  g_boLoadCylinder3 := FALSE;
  g_boLoadCylinder4 := FALSE;
  bFirstFlag := FALSE;
  CylinderDelay(IN := FALSE);
END_IF;
